/**
 * The Paw Journal, full articles.
 *
 * Original content written for ProxyPaw, grounded in published veterinary
 * guidance (AKC, American Humane, ASPCA, Preventive Vet, and practice blogs)
 * but rewritten for our audience: flat-dwellers in Gachibowli's gated
 * communities. Nothing here is copied text.
 *
 * Body format: a flat list of blocks so the reading view stays dumb-simple.
 *   h, section heading
 *   p, paragraph
 *   list, bullet list
 *   tip, highlighted ProxyPaw callout
 *
 * Every article carries a publication date (ISO YYYY-MM-DD). The journal
 * reads as one article a month; the blog index sorts on this field, so the
 * order of the array below does not matter.
 *
 * The hygiene and vet-checklist guides (April 2026 onwards) also list their
 * sources: pages from WSAVA, AAHA/AAFP, International Cat Care, the Cornell
 * Feline Health Center, the Merck Veterinary Manual, VCA Hospitals, PDSA and
 * the AKC that were read while writing. Only list a source if the claim is
 * actually on that page.
 */

export interface ArticleBlock {
  type: 'h' | 'p' | 'list' | 'tip';
  text?: string;
  items?: string[];
}

export interface ArticleSource {
  label: string;
  url: string;
}

export interface Article {
  slug: string;
  /** Publication date, ISO YYYY-MM-DD. */
  date: string;
  tag: string;
  title: string;
  dek: string;
  read: string;
  img: string;
  body: ArticleBlock[];
  /** Pages consulted for the article, shown at the end of the reading view. */
  sources?: ArticleSource[];
}

